import numpy as np

class RippleValley:
    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Ensure x is within bounds [-5, 5] per dimension
        x = np.clip(x, -5.0, 5.0)
        # Gaussian envelope centered at 0 with sigma=1.5
        envelope = np.exp(-0.5 * (x / 1.5)**2)
        # Ripple pattern (sine wave with frequency increasing with distance from center)
        ripple = np.sin(5 * x) * (1 + 0.5 * np.abs(x))
        # Combine envelope and ripple, then sum over dimensions
        return np.sum(envelope * ripple)

