import numpy as np

class WavyValley:

    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Ensure input is within bounds [-5, 5] per dimension
        x = np.clip(x, -5.0, 5.0)
        # Compute the wavy valley for each dimension
        # The frequency increases with dimension to create nested patterns
        return np.sum(2.0 * np.sin(2 * np.pi * x * (1 + 0.5 * np.arange(1, self.dim + 1))) ** 2 + x**2)
